-- Migration 0037: Atomic Ownership Transfer Function and Inverse Labor Tenure Trigger
--
-- 1. transfer_organization_ownership_temporal
--    Executes complete ownership transfer atomically in a single PostgreSQL function call,
--    enforcing immediate FOR UPDATE row lock on organizations, validating all invariants,
--    closing/opening role periods, synchronizing legacy memberships, and failing closed.
--
-- 2. check_employee_profile_labor_tenure_update / trg_check_employee_profile_labor_tenure
--    Enforces inverse labor tenure integrity: rejects UPDATE on employee_profiles.started_on or ended_on
--    if any existing employee_area_periods falls outside the new labor tenure range.

CREATE OR REPLACE FUNCTION transfer_organization_ownership_temporal(p_organization_id UUID, p_new_owner_person_id UUID, p_effective_date DATE, p_previous_owner_role TEXT DEFAULT 'ADMIN', p_current_owner_person_id UUID DEFAULT NULL) RETURNS TABLE (out_transferred BOOLEAN, out_organization_id UUID, out_previous_owner_person_id UUID, out_new_owner_person_id UUID, out_effective_date DATE, out_previous_owner_role TEXT) AS $$ DECLARE v_day_before DATE; v_new_owner_user_id UUID; v_new_owner_status TEXT; v_cur_owner_id UUID; v_cur_owner_person_id UUID; v_cur_owner_valid_from DATE; v_cur_owner_valid_to DATE; v_cur_owner_user_id UUID; BEGIN IF p_previous_owner_role NOT IN ('ADMIN', 'PLANNER') THEN RAISE EXCEPTION 'Previous owner role must be ADMIN or PLANNER'; END IF; IF p_effective_date > CURRENT_DATE THEN RAISE EXCEPTION 'Future-dated ownership transfers are not allowed without an automated scheduler'; END IF; v_day_before := p_effective_date - 1; PERFORM o.id FROM organizations o WHERE o.id = p_organization_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Organization % not found', p_organization_id; END IF; SELECT op.user_id, op.status INTO v_new_owner_user_id, v_new_owner_status FROM organization_people op WHERE op.id = p_new_owner_person_id AND op.organization_id = p_organization_id; IF NOT FOUND THEN RAISE EXCEPTION 'Target person % not found in organization %', p_new_owner_person_id, p_organization_id; END IF; IF v_new_owner_user_id IS NULL THEN RAISE EXCEPTION 'Target new owner person has no linked user_id'; END IF; IF v_new_owner_status <> 'ACTIVE' THEN RAISE EXCEPTION 'Target new owner person is not active'; END IF; IF NOT EXISTS (SELECT 1 FROM memberships m WHERE m.organization_id = p_organization_id AND m.user_id = v_new_owner_user_id) THEN RAISE EXCEPTION 'New owner must have an existing membership in the organization'; END IF; IF p_current_owner_person_id IS NOT NULL THEN SELECT prp.id, prp.organization_person_id, prp.valid_from, prp.valid_to, op.user_id INTO v_cur_owner_id, v_cur_owner_person_id, v_cur_owner_valid_from, v_cur_owner_valid_to, v_cur_owner_user_id FROM person_role_periods prp JOIN organization_people op ON op.id = prp.organization_person_id AND op.organization_id = prp.organization_id WHERE prp.organization_id = p_organization_id AND prp.organization_person_id = p_current_owner_person_id AND prp.role = 'OWNER' AND prp.valid_from <= p_effective_date AND (prp.valid_to IS NULL OR prp.valid_to >= p_effective_date) ORDER BY prp.valid_from DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Current owner period for person % not active on %', p_current_owner_person_id, p_effective_date; END IF; ELSE SELECT prp.id, prp.organization_person_id, prp.valid_from, prp.valid_to, op.user_id INTO v_cur_owner_id, v_cur_owner_person_id, v_cur_owner_valid_from, v_cur_owner_valid_to, v_cur_owner_user_id FROM person_role_periods prp JOIN organization_people op ON op.id = prp.organization_person_id AND op.organization_id = prp.organization_id WHERE prp.organization_id = p_organization_id AND prp.role = 'OWNER' AND prp.valid_from <= p_effective_date AND (prp.valid_to IS NULL OR prp.valid_to >= p_effective_date) ORDER BY prp.valid_from DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'No active OWNER role period found in organization % on %', p_organization_id, p_effective_date; END IF; END IF; IF v_cur_owner_person_id = p_new_owner_person_id THEN RAISE EXCEPTION 'Target owner cannot be the same as current owner'; END IF; IF v_cur_owner_valid_from > v_day_before THEN RAISE EXCEPTION 'Effective date % is on or before current owner start date %', p_effective_date, v_cur_owner_valid_from; END IF; IF EXISTS (SELECT 1 FROM person_role_periods prp WHERE prp.organization_id = p_organization_id AND ((prp.organization_person_id = v_cur_owner_person_id AND prp.valid_from > p_effective_date) OR (prp.organization_person_id = p_new_owner_person_id AND prp.valid_from >= p_effective_date) OR (prp.role = 'OWNER' AND prp.valid_from >= p_effective_date))) THEN RAISE EXCEPTION 'Ownership transfer conflict: Incompatible future role periods exist on or after effective date'; END IF; UPDATE person_role_periods SET valid_to = v_day_before, updated_at = NOW() WHERE person_role_periods.id = v_cur_owner_id; INSERT INTO person_role_periods (organization_id, organization_person_id, role, valid_from, valid_to, source, created_at, updated_at) VALUES (p_organization_id, v_cur_owner_person_id, p_previous_owner_role, p_effective_date, NULL, 'USER', NOW(), NOW()); UPDATE person_role_periods SET valid_to = v_day_before, updated_at = NOW() WHERE person_role_periods.organization_id = p_organization_id AND person_role_periods.organization_person_id = p_new_owner_person_id AND person_role_periods.valid_from <= v_day_before AND (person_role_periods.valid_to IS NULL OR person_role_periods.valid_to >= p_effective_date); INSERT INTO person_role_periods (organization_id, organization_person_id, role, valid_from, valid_to, source, created_at, updated_at) VALUES (p_organization_id, p_new_owner_person_id, 'OWNER', p_effective_date, NULL, 'USER', NOW(), NOW()); IF v_cur_owner_user_id IS NOT NULL THEN UPDATE memberships SET role = p_previous_owner_role, scoped_area_id = NULL, planner_scope_type = NULL WHERE memberships.organization_id = p_organization_id AND memberships.user_id = v_cur_owner_user_id; END IF; IF v_new_owner_user_id IS NOT NULL THEN UPDATE memberships SET role = 'OWNER', scoped_area_id = NULL, planner_scope_type = NULL WHERE memberships.organization_id = p_organization_id AND memberships.user_id = v_new_owner_user_id; END IF; RETURN QUERY SELECT true, p_organization_id, v_cur_owner_person_id, p_new_owner_person_id, p_effective_date, p_previous_owner_role; END; $$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_employee_profile_labor_tenure_update() RETURNS TRIGGER AS $$ BEGIN IF (NEW.started_on IS DISTINCT FROM OLD.started_on) OR (NEW.ended_on IS DISTINCT FROM OLD.ended_on) THEN IF NEW.started_on IS NOT NULL AND EXISTS (SELECT 1 FROM employee_area_periods eap WHERE eap.employee_profile_id = NEW.id AND eap.organization_id = NEW.organization_id AND eap.valid_from < NEW.started_on) THEN RAISE EXCEPTION 'Cannot update employee profile labor tenure: existing area assignment starts before new started_on (%)', NEW.started_on; END IF; IF NEW.ended_on IS NOT NULL AND EXISTS (SELECT 1 FROM employee_area_periods eap WHERE eap.employee_profile_id = NEW.id AND eap.organization_id = NEW.organization_id AND (eap.valid_to IS NULL OR eap.valid_to > NEW.ended_on)) THEN RAISE EXCEPTION 'Cannot update employee profile labor tenure: existing area assignment extends beyond new ended_on (%)', NEW.ended_on; END IF; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_employee_profile_labor_tenure ON employee_profiles;

CREATE CONSTRAINT TRIGGER trg_check_employee_profile_labor_tenure
  AFTER UPDATE OF started_on, ended_on ON employee_profiles
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  EXECUTE FUNCTION check_employee_profile_labor_tenure_update();
